import { useState } from "react";
import { registerUser } from "../services/authService";
import { mainLogo } from "../assets/images";

export default function SignupScreen({ onNavigate }) {
  const [form, setForm] = useState({
    name: "",
    contactNumber: "",
    province: "",
    municipality: "",
    barangay: "",
    password: "",
    confirmPassword: "",
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // ✅ separate toggles
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const set = (key) => (e) =>
    setForm((f) => ({ ...f, [key]: e.target.value }));

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");

    const {
      name,
      contactNumber,
      province,
      municipality,
      barangay,
      password,
      confirmPassword,
    } = form;

    if (!name || !contactNumber || !province || !password || !confirmPassword) {
      setError("Please fill in all required fields.");
      return;
    }

    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    if (contactNumber.length < 10) {
      setError("Please enter a valid contact number.");
      return;
    }

    setLoading(true);

    const registrationData = {
      username: contactNumber.trim(),
      password: password,
      full_name: name.trim(),
      contact_number: contactNumber.trim(),
      province: province.trim(),
      municipality: municipality.trim(),
      barangay: barangay.trim(),
    };

    const { error: regError } = await registerUser(registrationData);

    if (regError) {
      setError(regError);
      setLoading(false);
      return;
    }

    onNavigate("login", { phone: contactNumber.trim() });
    setLoading(false);
  };

  // 👁️ reusable eye icon
  const EyeIcon = ({ off }) =>
    off ? (
      <svg width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2">
        <path d="M1 1l22 22" />
        <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94" />
        <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19" />
      </svg>
    ) : (
      <svg width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2">
        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
        <circle cx="12" cy="12" r="3" />
      </svg>
    );

  return (
    <div className="auth-root" style={{ backgroundColor: "#dce5d2" }}>
      <div className="auth-card" style={{ maxWidth: 480 }}>
        <div className="auth-logo">
          <img src={mainLogo} alt="logo" style={{ width: 52 }} />
          <div>Scare<span>Crow</span></div>
        </div>

        <h1>SIGN UP</h1>

        <form onSubmit={handleSignUp}>
          <input placeholder="FULL NAME" value={form.name} onChange={set("name")} />

          <input
            placeholder="CONTACT NUMBER"
            value={form.contactNumber}
            onChange={set("contactNumber")}
          />

          <input placeholder="PROVINCE" value={form.province} onChange={set("province")} />

          {/* PASSWORD */}
          <div style={{ position: "relative" }}>
            <input
              type={showPassword ? "text" : "password"}
              placeholder="PASSWORD"
              value={form.password}
              onChange={set("password")}
              style={{ paddingRight: "40px" }}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              style={eyeBtnStyle}
            >
              <EyeIcon off={showPassword} />
            </button>
          </div>

          {/* CONFIRM PASSWORD */}
          <div style={{ position: "relative", marginTop: 10 }}>
            <input
              type={showConfirmPassword ? "text" : "password"}
              placeholder="CONFIRM PASSWORD"
              value={form.confirmPassword}
              onChange={set("confirmPassword")}
              style={{ paddingRight: "40px" }}
            />
            <button
              type="button"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              style={eyeBtnStyle}
            >
              <EyeIcon off={showConfirmPassword} />
            </button>
          </div>

          {/* mismatch hint */}
          {form.confirmPassword && form.password !== form.confirmPassword && (
            <p style={{ color: "red" }}>Passwords do not match</p>
          )}

          {error && <div style={{ color: "red" }}>{error}</div>}

          <button type="submit" disabled={loading}>
            {loading ? "Loading..." : "SIGN UP"}
          </button>
        </form>
      </div>
    </div>
  );
}

// 👁️ shared button style
const eyeBtnStyle = {
  position: "absolute",
  right: "10px",
  top: "50%",
  transform: "translateY(-50%)",
  background: "none",
  border: "none",
  cursor: "pointer",
  color: "#6b7c61",
};
